import{_ as r,a as e,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读一：乾坤至师比 · 01 乾：刚健也要知进退至03 屯：初生之难与建立秩序","description":"对读《周易》与《周易正义》，逐爻理解乾、坤、屯、蒙、需、讼、师、比八卦。","frontmatter":{"title":"六十四卦详读一：乾坤至师比 · 01 乾：刚健也要知进退至03 屯：初生之难与建立秩序","description":"对读《周易》与《周易正义》，逐爻理解乾、坤、屯、蒙、需、讼、师、比八卦。","splitFrom":"life/personal/yijing/hexagrams-01-08.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读一：乾坤至师比","summary":"对读《周易》与《周易正义》，逐爻理解乾、坤、屯、蒙、需、讼、师、比八卦。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读一：乾坤至师比","link":"/life/personal/yijing/hexagrams-01-08"},"next":{"text":"六十四卦详读一：乾坤至师比 · 04 蒙：如何问、如何教、如何养成至06 讼：争执的边界与开端","link":"/life/personal/yijing/hexagrams-01-08-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读一：乾坤至师比","link":"/life/personal/yijing/hexagrams-01-08"},"next":{"text":"六十四卦详读一：乾坤至师比 · 04 蒙：如何问、如何教、如何养成至06 讼：争执的边界与开端","link":"/life/personal/yijing/hexagrams-01-08-part-02"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-01-08-part-01.md","filePath":"life/personal/yijing/hexagrams-01-08-part-01.md"}'),o={name:"life/personal/yijing/hexagrams-01-08-part-01.md"};function s(i,t,d,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读一-乾坤至师比-·-01-乾-刚健也要知进退至03-屯-初生之难与建立秩序" tabindex="-1">六十四卦详读一：乾坤至师比 · 01 乾：刚健也要知进退至03 屯：初生之难与建立秩序 <a class="header-anchor" href="#六十四卦详读一-乾坤至师比-·-01-乾-刚健也要知进退至03-屯-初生之难与建立秩序" aria-label="Permalink to &quot;六十四卦详读一：乾坤至师比 · 01 乾：刚健也要知进退至03 屯：初生之难与建立秩序&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-01-08">返回分篇目录</a></p><p>这一组从天地、生长与启蒙，进入等待、争讼、组织与亲比。卦序提供阅读线索，并不是每个人都必须按顺序经历的人生阶段。先读卦辞与《大象》，再把六爻自下而上读一遍，留意同一卦里为什么既有“吉”，又有“凶”。</p><p>本文实际对读维基文库《周易》各卦及王弼注、孔颖达疏《周易正义》对应篇。引文保留繁体及“无”等古字，标点为便于阅读所加；网上录文的异体、断句与古注解释并不完全一致，下文必要时说明。表格左栏是古籍原文，右栏及“读法”是本篇白话概括，不是古人原句。古代占筮判断属于其历史语境，不能当作科学预测；君臣、婚姻与性别秩序也不直接作为现代规范。</p><h2 id="六十四卦详读一-乾坤至师比" tabindex="-1">六十四卦详读一：乾坤至师比 <a class="header-anchor" href="#六十四卦详读一-乾坤至师比" aria-label="Permalink to &quot;六十四卦详读一：乾坤至师比 {#六十四卦详读一-乾坤至师比}&quot;">​</a></h2><p>这一组从天地、生长与启蒙，进入等待、争讼、组织与亲比。卦序提供阅读线索，并不是每个人都必须按顺序经历的人生阶段。先读卦辞与《大象》，再把六爻自下而上读一遍，留意同一卦里为什么既有“吉”，又有“凶”。</p><p>本文实际对读维基文库《周易》各卦及王弼注、孔颖达疏《周易正义》对应篇。引文保留繁体及“无”等古字，标点为便于阅读所加；网上录文的异体、断句与古注解释并不完全一致，下文必要时说明。表格左栏是古籍原文，右栏及“读法”是本篇白话概括，不是古人原句。古代占筮判断属于其历史语境，不能当作科学预测；君臣、婚姻与性别秩序也不直接作为现代规范。</p><h2 id="gua-01" tabindex="-1">01 乾：刚健也要知进退 <a class="header-anchor" href="#gua-01" aria-label="Permalink to &quot;01 乾：刚健也要知进退 {#gua-01}&quot;">​</a></h2><p><strong>卦符：䷀　上卦：乾 ☰（天）　下卦：乾 ☰（天）。</strong></p><p><strong>卦辞原文</strong>：乾：元亨，利貞。</p><p><strong>白话概括</strong>：乾呈现持续发动、创造的力量。“元亨利贞”在《文言》与《正义》中被展开为四德；从古经占辞看，也存在不同断读方式，不宜直接缩成“做什么都成功”。六爻全阳，却并非越高越好：初爻要求潜藏，上爻警告过亢，中间才展开适时行动的条件。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：潛龍勿用。</td><td>龙尚潜伏，条件未成熟时不急于施展。这里的“勿用”是时机判断，不是否定能力。</td></tr><tr><td>九二：見龍在田，利見大人。</td><td>龙出现于田野，德能开始显现。“见”前一处读现；“大人”在古注中既可指有德者，也涉及谁见谁的不同解释。</td></tr><tr><td>九三：君子終日乾乾，夕惕若，厲，无咎。</td><td>持续努力，同时保有警惕。处在危险位置，不能用勤奋替代对风险的认识。</td></tr><tr><td>九四：或躍在淵，无咎。</td><td>在跃进与停留之间试探；“或”保留不确定性，不要求每一次都向上跃。</td></tr><tr><td>九五：飛龍在天，利見大人。</td><td>能力与位置较为相称，行动影响广泛；此时仍需与有德有识的人相遇、相助。</td></tr><tr><td>上九：亢龍，有悔。</td><td>过高、过满而不知退，容易产生悔恨。终点不是无限加码。</td></tr><tr><td>用九：見羣龍无首，吉。</td><td>用九是乾卦特有的附辞，不是第七爻。古注着重“不自为首”，可理解为刚健而不独占主导。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“天行健，君子以自強不息。”</p><p><strong>解释</strong>：取天运行不息为修养的象征。《正义》区分“天”的形体与“乾”的作用，强调人学习的是健行的方式，不是模仿一个可触摸的天体。自强因此包括长期修养、审时与收敛，不等于持续透支。</p><p><strong>整体读法与误区</strong>：把六条龙辞连起来，重点是“处什么位置，就承担什么限制”。九三有危险却可无咎，上九尊高却有悔，说明卦中评价不能只看地位。用九又把个人独尊松开，使乾的力量不落入专断。把“飞龙在天”单独当作升官发财的保证，会丢掉全卦最关键的退与戒。</p><p><strong>细读线索</strong>：九二与九五都说利见大人，前者在下卦之中，后者在上卦之中。王弼并不只把大人固定为九五，而强调九二虽无君位，也可以有君德。这个区别让读者把实际德能与名位分开。九三、九四则都处在上下转换附近，分别出现惕与或；与其急着给每爻安排一个年龄，不如先看它如何刻画不稳定的位置。六爻的时并不等于一张人人适用的年龄表。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B9%BE" target="_blank" rel="noopener noreferrer">《周易·乾》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/01%E4%B9%BE" target="_blank" rel="noopener noreferrer">《周易正义·上经乾传卷一·乾》</a>。</p><h2 id="gua-02" tabindex="-1">02 坤：承载、成全与守正 <a class="header-anchor" href="#gua-02" aria-label="Permalink to &quot;02 坤：承载、成全与守正 {#gua-02}&quot;">​</a></h2><p><strong>卦符：䷁　上卦：坤 ☷（地）　下卦：坤 ☷（地）。</strong></p><p><strong>卦辞原文</strong>：坤：元亨，利牝馬之貞。君子有攸往，先迷後得主，利西南得朋，東北喪朋，安貞吉。</p><p><strong>白话概括</strong>：坤以地与牝马表现承接、生养、持久行进的能力。“先迷后得主”在古注中与响应、配合有关；“西南得朋、东北丧朋”属于传统方位与阴阳解释，不能直接转成现代出行指南。“利”字的归属也有不同断句。坤不是没有行动力，而是行动从承载关系中展开。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：履霜，堅冰至。</td><td>踩到薄霜，想到严寒可能继续积累。关注细微征兆与渐变，不等于看见一点不顺就断言灾祸必来。</td></tr><tr><td>六二：直方大，不習无不利。</td><td>正直、端方、宽广构成这一爻的理想。《正义》强调地自然而生的德性，“不习”不能泛化成不必学习。</td></tr><tr><td>六三：含章，可貞。或從王事，无成有終。</td><td>含藏美质，参与公共事务而完成责任。古注的“无成”偏向不自居首功，不是做事没有成果。</td></tr><tr><td>六四：括囊，无咎无譽。</td><td>扎紧袋口，以谨慎减少风险；没有过错也未必得到赞誉。它描述特定闭塞情境，不能当成永远沉默的原则。</td></tr><tr><td>六五：黃裳，元吉。</td><td>黄取中、裳取下，古注据此说明内在有美而居处谦下。重点在德与位置相称。</td></tr><tr><td>上六：龍戰于野，其血玄黃。</td><td>阴阳关系走到争胜相伤的极端，景象惨烈。承接若变成争夺同一种权位，也可能破坏合作。</td></tr><tr><td>用六：利永貞。</td><td>坤卦特有附辞，强调持久守正；顺从必须有稳定的原则，不是随人摆布。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“地勢坤，君子以厚德載物。”</p><p><strong>解释</strong>：大地承载不同生命，君子据此扩充容纳与养成的德行。《正义》同时指出柔顺须兼有贞固，过刚与过柔都难求安。厚德包含辨别和承担，并不要求无条件承受伤害。</p><p><strong>整体读法与误区</strong>：与<a href="/life/personal/yijing/hexagrams-01-08-part-01#gua-01">乾卦</a>对读，乾重发动，坤重成形；两者不是“强者有价值、配合者没价值”的排序。古传把坤比附妻道、臣道，反映当时秩序，现代阅读应区分历史解释与今日伦理。六四的无誉、六三的有终，也提醒我们：有些必要工作不耀眼，仍应被认真完成。</p><p><strong>细读线索</strong>：坤六爻可以分两条线索读：霜至冰、龙战于野呈现积渐走向极端；直方大、含章、黄裳则讨论内在德性怎样落实。这样就能看出坤并非只有柔软的一面。括囊的无咎无誉又单独保留了谨慎的代价：避开损害，可能也没有发挥的机会。对照这些不同评价，可以练习区分没有过失、获得肯定和完成责任，三者在经文中并不重合。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%A4" target="_blank" rel="noopener noreferrer">《周易·坤》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/01%E5%9D%A4" target="_blank" rel="noopener noreferrer">《周易正义·上经乾传卷一·坤》</a>。</p><h2 id="gua-03" tabindex="-1">03 屯：初生之难与建立秩序 <a class="header-anchor" href="#gua-03" aria-label="Permalink to &quot;03 屯：初生之难与建立秩序 {#gua-03}&quot;">​</a></h2><p><strong>卦符：䷂　上卦：坎 ☵（水、险）　下卦：震 ☳（雷、动）。屯读 zhūn。</strong></p><p><strong>卦辞原文</strong>：屯：元亨，利貞。勿用有攸往，利建侯。</p><p><strong>白话概括</strong>：震要动，坎却在前，形成开始发展时的阻滞。《正义》把屯解释为刚柔初交、秩序未定之难。因此“勿用有攸往”与“利建侯”不冲突：不宜盲目前进，却宜建立足以安定局面的组织与责任。这里的侯有古代政治含义，现代只能作有限类比。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：磐桓，利居貞，利建侯。</td><td>徘徊不进，先稳住原则与基础。“磐桓”也写作盘桓；停留不是贪图安逸。</td></tr><tr><td>六二：屯如邅如，乘馬班如，匪寇婚媾，女子貞不字，十年乃字。</td><td>行进受阻，婚姻迟滞。“匪寇婚媾”与“字”的解释有异说；王、孔一系从爻际阻隔说明，不宜据此预测婚期。</td></tr><tr><td>六三：即鹿无虞，惟入于林中，君子幾不如舍，往吝。</td><td>追鹿而没有熟悉山林的虞人引导，容易徒入林中。缺少信息与支持，放弃可能更合宜；“几”也有语辞、知几等异解。</td></tr><tr><td>六四：乘馬班如，求婚媾，往吉，无不利。</td><td>同样是车马徘徊，此处却可主动寻求合适联结。不能只凭相似字面给所有爻同一结论。</td></tr><tr><td>九五：屯其膏，小貞吉，大貞凶。</td><td>恩泽积滞而不能广施，局部尚可，承担过大的事务则有危险。关于大小所指，历来有不同解释。</td></tr><tr><td>上六：乘馬班如，泣血漣如。</td><td>久困而无出路，悲痛至极。经文并没有承诺每一种困难都自动转好。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“雲雷，屯；君子以經綸。”</p><p><strong>解释</strong>：云雷酝酿而未舒展，取象于整理经纬、组织事务。《正义》以经纬、纲纶解释经纶，强调在纷乱中安排关系，而非靠一次冲刺解决一切。</p><p><strong>整体读法与误区</strong>：屯最有用的比较是六二、六四与上六：都出现“乘马班如”，结局却分别是等待、可往、悲困，因为关系与处境不同。它既不一概鼓励坚持，也不一概要求退出。现代类比时可问“困难来自阶段、信息还是结构”，但不要把“建侯”简单包装成创业必胜，也不要将“十年”机械换算为现实日历。</p><p><strong>细读线索</strong>：卦辞既说元亨，又说勿往，读者最容易把它看作自相矛盾。古注则区分整体可通的方向与当下不能躁进的处境；利建侯提供的是组织条件。初九虽然居最下，却被解释为以贵下贱、因此得民，说明主事能力未必来自最高的位置。九五反而因膏泽不能广施而受限制。把这两爻并读，能看到名位、能力、资源流通在屯难中并不必然一致。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%AF" target="_blank" rel="noopener noreferrer">《周易·屯》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/01%E5%B1%AF" target="_blank" rel="noopener noreferrer">《周易正义·上经乾传卷一·屯》</a>。</p>',37)])])}const f=r(o,[["render",s]]);export{c as __pageData,f as default};
